package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.util.*;
public class DocumentActivity extends Activity{@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);String id=getIntent().getStringExtra("id");DocumentStore.Item x=DocumentStore.find(this,id);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Analyse du catalogue",27,true));if(x==null){r.addView(Ui.text(this,"Document introuvable.",15,false));setContentView(Ui.wrap(this,r));return;}r.addView(Ui.text(this,x.name,21,true));String sector;try{sector=DataNormalizer.Sector.valueOf(x.sector).label;}catch(Exception e){sector=x.sector;}r.addView(Ui.text(this,"Norme/profil : "+sector+"\nFiches : "+x.rows+" · Colonnes : "+x.columns+"\nQualité : "+x.score+" %\nCellules vides : "+x.emptyCells+" · Doublons : "+x.duplicates+"\nCellules corrigées : "+x.changedCells,15,false));DataBarView bar=new DataBarView(this);bar.setValues(x.score,100-x.score,Math.min(20,x.duplicates+x.emptyCells));r.addView(bar,new LinearLayout.LayoutParams(-1,Ui.dp(this,44)));Button diag=Ui.primary(this,"Diagnostic complet du catalogue");diag.setOnClickListener(v->{Intent i=new Intent(this,DocumentDiagnosticActivity.class);i.putExtra("id",x.id);startActivity(i);});r.addView(diag);Button map=Ui.secondary(this,"Voir la correspondance champ par champ");map.setOnClickListener(v->{Intent i=new Intent(this,MappingActivity.class);i.putExtra("id",x.id);startActivity(i);});r.addView(map);Button share=Ui.secondary(this,"Partager le CSV nettoyé");share.setOnClickListener(v->{try{List<List<String>> rows=DocumentStore.read(this,x);Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/csv");i.putExtra(Intent.EXTRA_SUBJECT,"Catalogue normalisé - "+x.name);i.putExtra(Intent.EXTRA_TEXT,SpreadsheetReader.toCsv(rows));startActivity(Intent.createChooser(i,"Partager"));}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}});r.addView(share);r.addView(Ui.text(this,"Traçabilité : colonne d’origine → champ normalisé → champ cible → exemple avant/après → statut → justification. Une validation humaine reste requise.",13,false));setContentView(Ui.wrap(this,r));}}
